<div class="form-group d-none" id="replacement-uuid-group"><label>UUID del CFDI sustituto</label><p class="text-muted">Indique el UUID del CFDI que sustituye a esta factura.</p><input type="text" class="form-control" name="replacement_uuid" id="replacement-uuid" maxlength="36" pattern="[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}"></div>
<div class="alert alert-warning">La cancelación fiscal conserva la factura, su XML, PDF, UUID e historial y no cancela la venta administrativa.<br><strong>Solicitar la cancelación consume 1 timbre comercial iKontrol.</strong><br>Saldo utilizable: <?php echo(int)$balance['usable']; ?> timbres.</div><?php if((int)$balance['usable']<1){?><div class="alert alert-danger">No cuenta con timbres suficientes para solicitar la cancelación.</div><?php }?></div>
<div id="cancellation-result"></div><div class="modal-footer"><button type="button" class="btn btn-default" data-bs-dismiss="modal">Cerrar</button><button type="submit" id="cancellation-submit" class="btn btn-danger" <?php echo(int)$balance['usable']<1?'disabled':''; ?>>Solicitar cancelación y consumir 1 timbre</button></div><?php echo form_close(); ?>
<script src="<?php echo base_url('assets/js/fiscal-cancellation-modal.js'); ?>"></script>
<script>$(document).ready(function(){var form=$('#fiscal-cancellation-form'),reason=$('#cancellation-reason'),group=$('#replacement-uuid-group'),uuid=$('#replacement-uuid'),submit=$('#cancellation-submit'),result=$('#cancellation-result'),originalText=submit.text(),state='idle';function safe(value){return $('<div>').text(value||'No fue posible solicitar la cancelación.').html();}function lock(){var body=form.find('.modal-body');body.addClass('hide');body.after('<div class="modal-mask"><div class="circle-loader"></div></div>');form.find('.modal-mask').css({width:(body.width()+22)+'px',height:body.outerHeight()+'px'});form.find('button').prop('disabled',true);submit.text('Procesando...');}function unlock(){form.find('.modal-body').removeClass('hide');form.find('.modal-mask').remove();form.find('button').prop('disabled',false);submit.text(originalText);}function render(outcome){state=outcome.state;unlock();if(outcome.state==='ambiguous'){submit.prop('disabled',true).text('Solicitud bloqueada');result.html('<div class="alert alert-warning">'+safe(outcome.message)+' Consulte el estado antes de volver a intentar.</div>');return;}if(outcome.state==='retryable')result.html('<div class="alert alert-danger">'+safe(outcome.message)+'</div>');}function sync(){var required=reason.val()==='01';group.toggleClass('d-none',!required);uuid.prop('required',required);if(!required)uuid.val('');}function reloadList(){var table=$('#fiscal-invoices-table');if(table.length)table.appTable({reload:true});else location.reload();}reason.on('change',sync);sync();form.on('submit',function(event){event.preventDefault();var start=FiscalCancellationModal.begin(state);if(!start.accepted)return false;state=start.state;result.empty();lock();$.ajax({url:form.attr('action'),type:'POST',dataType:'json',data:form.serialize()}).done(function(response){if(response.csrf)form.find('input[name="'+response.csrf.name+'"]').val(response.csrf.hash);var outcome=FiscalCancellationModal.fromResponse(response);if(outcome.state==='complete'){state='complete';unlock();$('#ajaxModal').modal('hide');appAlert.success(outcome.message);reloadList();return;}render(outcome);}).fail(function(xhr){render(FiscalCancellationModal.fromTransportError(xhr));});return false;});$('#ajaxModal').off('hide.bs.modal.fiscalCancellation').on('hide.bs.modal.fiscalCancellation',function(event){if(state==='processing')event.preventDefault();});});</script>
